public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Type[] resolvedTypes = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof Class<?>) {
            resolvedTypes[i] = (Class<?>) actualTypeArgument;
        } else if (actualTypeArgument instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
            Type resolvedType = resolveTypeVariable(typeVariable, targetType);
            if (resolvedType instanceof Class<?>) {
                resolvedTypes[i] = (Class<?>) resolvedType;
            } else {
                return null;
            }
        }
    }

    return resolvedTypes;
}

private static Type resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
    for (int i = 0; i < typeParameters.length; i++) {
        if (typeParameters[i].equals(typeVariable)) {
            return targetType.getGenericSuperclass();
        }
    }

    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof Class<?>) {
        return resolveTypeVariable(typeVariable, (Class<?>) genericSuperclass);
    }

    Type[] interfaces = targetType.getGenericInterfaces();
    for (Type iface : interfaces) {
        Type resolvedType = resolveTypeVariable(typeVariable, (Class<?>) iface);
        if (resolvedType != null) {
            return resolvedType;
        }
    }

    return null;
}
