    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    long result = year * 10000 + month * 100;
    while ((result + dayStep) > year * 10000 + month * 100 + day) {
        day--;
        if (day == 0) {
            month--;
            if (month == 0) {
                year--;
                month = 12;
            }
            day = getDaysInMonth(year, month);
        }
    }
